/**
 * Per-gene mutation of a binary genome at a fixed mutation rate.
 */
public class GeneMutator {

    public static int[] mutate(int[] genes, double rate, long seed) {
        java.util.Random rng = new java.util.Random(seed);
        int[] mutated = java.util.Arrays.copyOf(genes, genes.length);
        for (int i = 0; i < mutated.length; i++) {
            if (rng.nextDouble() < rate) {
                mutated[i] = 1 - mutated[i];
            }
        }
        return mutated;
    }

    public static int mutationCount(int[] before, int[] after) {
        int changed = 0;
        for (int i = 0; i < before.length; i++) {
            if (before[i] != after[i]) {
                changed++;
            }
        }
        return changed;
    }
}
